import os

files_to_patch = {
    'compute_signals.py': {
        'old': 'import argparse\nimport json\nimport logging\nimport os\nfrom pathlib import Path\nimport re',
        'new': 'import argparse\nimport json\nimport logging\nimport os\nfrom pathlib import Path\nimport re\n\nos.environ.setdefault("HF_HOME", "/root/autodl-tmp/.hf_cache")\nos.environ.setdefault("HF_DATASETS_OFFLINE", "1")\nos.environ.setdefault("TRANSFORMERS_OFFLINE", "1")',
    },
}

emb_old = 'HF_HOME = os.environ.get("HF_HOME", "/root/autodl-tmp/.hf_cache")\nos.environ["HF_HOME"] = HF_HOME'
emb_new = 'HF_HOME = os.environ.get("HF_HOME", "/root/autodl-tmp/.hf_cache")\nos.environ["HF_HOME"] = HF_HOME\nos.environ.setdefault("HF_DATASETS_OFFLINE", "1")\nos.environ.setdefault("TRANSFORMERS_OFFLINE", "1")'

for fname in ['signal_embedding.py', 'signal_minkpp.py', 'signal_selfcritique.py']:
    files_to_patch[fname] = {'old': emb_old, 'new': emb_new}

for fname, patch in files_to_patch.items():
    with open(fname) as f:
        content = f.read()
    if patch['old'] in content:
        content = content.replace(patch['old'], patch['new'], 1)
        with open(fname, 'w') as f:
            f.write(content)
        print(f'PATCHED: {fname}')
    elif patch['new'].split('\n')[-1] in content:
        print(f'ALREADY PATCHED: {fname}')
    else:
        print(f'WARNING: pattern not found in {fname}')
PYEOF
python /tmp/patch_offline.py

